(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),q=s=>document.querySelector(s),allowed=()=>shared?!!project&&management():manager(),dlg=()=>q(shared?'#sharedDialog':'#details'),root=()=>q(shared?'#sharedDetail':'#detailBody');let removed=[];if(!shared){try{removed=JSON.parse(localStorage.getItem('samandis-demo-trash-v1'))||[]}catch{}}
if(!shared&&removed.length){const ids=new Set(removed.map(t=>t.id));tasks=tasks.filter(t=>!ids.has(t.id));}
const saveRemoved=()=>localStorage.setItem('samandis-demo-trash-v1',JSON.stringify(removed));
function show(html){root().innerHTML='<div class="shared-task-head"><h2>حذف و بازیابی کار</h2><button type="button" id="trashClose" class="secondary">بازگشت</button></div>'+html;if(!dlg().open)dlg().showModal();q('#trashClose').onclick=()=>dlg().close()}
async function change(t,restore){if(!allowed())return;const b=q('#confirmTrash');if(b)b.disabled=true;try{if(shared){await rpc('sm_trash_task',{p_task:t.id,p_revision:t.revision,p_restore:restore});await refresh()}else{if(restore){if(!tasks.some(x=>x.id===t.id))tasks.push(t);removed=removed.filter(x=>x.id!==t.id)}else{removed.push({...t});tasks=tasks.filter(x=>x.id!==t.id)}saveRemoved();save()}dlg().close();document.body.classList.remove('task-drawer-open');(shared?message:toast)(restore?'کار بازیابی شد.':'کار به حذف‌شده‌ها منتقل شد؛ فایل‌ها و سوابق محفوظ‌اند.')}catch(e){(shared?message:toast)(shared?failure(e):e.message)}finally{if(b)b.disabled=false}}
function confirm(t,restore=false){show('<p>'+ (restore?'این کار به فهرست برگردد؟':'این کار از فهرست حذف شود؟ فایل‌ها و سوابق باقی می‌مانند و می‌توانید آن را بازیابی کنید.')+'</p><p><b>'+esc(t.title)+'</b></p><button class="primary" id="confirmTrash">'+(restore?'بازیابی کار':'انتقال به حذف‌شده‌ها')+'</button>');q('#confirmTrash').onclick=()=>change(t,restore)}
function trashList(){if(!allowed())return;const rows=shared?sharedDeleted:removed;show('<h3>کارهای حذف‌شده</h3>'+ (rows.length?rows.map(t=>'<div class="shared-member"><b>'+esc(t.title)+'</b><button class="secondary" data-restore-task="'+esc(t.id)+'">بازیابی</button></div>').join(''):'<p>کاری حذف نشده است.</p>'));root().querySelectorAll('[data-restore-task]').forEach(b=>b.onclick=()=>confirm(rows.find(t=>t.id===b.dataset.restoreTask),true))}
const priorRender=render;render=function(...args){const result=priorRender(...args);q('#taskTrashList')?.remove();if(allowed()){const b=document.createElement('button');b.id='taskTrashList';b.className='signout';b.textContent='حذف‌شده‌ها';b.onclick=trashList;q(shared?'#accountTools':'.header-tools')?.append(b)}return result};
const priorDetail=detail;detail=async function(id,...args){await priorDetail(id,...args);if(!allowed()||!dlg().open)return;const t=tasks.find(x=>x.id===id);if(!t)return;root().querySelector('#trashThisTask')?.remove();const b=document.createElement('button');b.id='trashThisTask';b.type='button';b.className='secondary';b.textContent='حذف کار';b.style.color='#a33e42';b.onclick=()=>confirm(t);root().querySelector('.shared-task-head,.dialog-head')?.after(b)};
render();
})();
